package clinic.backend.entity;

import java.util.Objects;
import java.util.UUID;

import jakarta.persistence.Column;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;
import jakarta.persistence.PostLoad;
import jakarta.persistence.PostPersist;
import jakarta.persistence.Transient;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.NoArgsConstructor;
import org.springframework.data.domain.Persistable;

/**
 * Base for entities whose primary key is a UUIDv7 generated by the application (docs/database-conventions.md).
 *
 * <p>The ID is assigned before persisting, so Spring Data cannot tell a new entity from a loaded one by its ID.
 * {@link #isNew()} tracks it instead, letting {@code save} insert without a preceding select.
 */
@Getter
@NoArgsConstructor(access = AccessLevel.PROTECTED)
@MappedSuperclass
public abstract class UuidEntity implements Persistable<UUID> {

    @Id
    @Column(name = "id", nullable = false, updatable = false)
    private UUID id;

    @Transient
    @Getter(AccessLevel.NONE)
    private boolean isNew = true;

    protected UuidEntity(UUID id) {
        this.id = Objects.requireNonNull(id, "id");
    }

    @Override
    public boolean isNew() {
        return isNew;
    }

    @PostLoad
    @PostPersist
    void markNotNew() {
        isNew = false;
    }
}
